export const DIGITAL_FOOTPRINT_ACTIVITIES = [
{n:1,type:"mcq",micro:"Apa itu jejak digital",q:"'Jejak digital' adalah...",options:["Kumpulan semua data & aktivitas yang kamu tinggalkan saat memakai internet, sengaja atau tidak","Hanya foto dan video yang kamu unggah sendiri ke media sosial dengan sengaja, tidak termasuk hal lainnya","Jejak kaki yang tertinggal di lantai dekat komputer setelah kamu selesai memakainya"],answer:0,explain:"Setiap pencarian, unggahan, komentar, & bahkan klik meninggalkan data yang bisa terkumpul jadi gambaran tentang dirimu.",hint:"Semua data & aktivitas online, atau hanya unggahan sendiri?"},
{n:2,type:"mcq",micro:"Jejak aktif vs pasif",q:"'Jejak aktif' adalah yang kamu buat sengaja (unggahan, komentar); 'jejak pasif' adalah...",options:["Sama persis dengan jejak aktif, yaitu data yang kamu buat sendiri dengan sengaja saat memposting","Data yang terkumpul tanpa kamu sadari secara langsung, mis. riwayat pencarian, lokasi, waktu online","Jejak yang tidak pernah ada, karena semua aktivitas daring selalu langsung hilang tanpa bekas"],answer:1,explain:"Jejak pasif terkumpul di belakang layar: situs mencatat kunjunganmu, aplikasi mencatat lokasi, meski kamu tidak 'memposting' apa pun.",hint:"Terkumpul tanpa disadari langsung, atau tidak pernah ada?"},
{n:3,type:"mcq",micro:"Contoh jejak digital",q:"Manakah yang TERMASUK jejak digital?",options:["Buku catatan tulisan tangan yang disimpan di rumahmu dan tidak difoto atau diunggah","Percakapan tatap muka di taman yang tidak direkam dan tidak lewat alat apa pun","Komentar di video, riwayat pencarian, & lokasi yang tercatat aplikasi peta"],answer:2,explain:"Apa pun yang melibatkan perangkat & internet biasanya meninggalkan catatan digital di suatu tempat.",hint:"Yang melibatkan internet, atau yang benar-benar offline?"},
{n:4,type:"mcq",micro:"Jejak digital cenderung permanen",q:"Kenapa jejak digital sering disebut 'sulit dihapus sepenuhnya'?",options:["Bisa disalin, dibagikan, & disimpan orang lain sebelum kamu sempat menghapusnya, & tersimpan di banyak server","Karena internet menyimpannya hanya di satu tempat tunggal yang bisa langsung dihapus kapan saja oleh pemiliknya","Karena jejak digital selalu hilang otomatis dalam sehari, sehingga tidak ada yang perlu dikhawatirkan lagi"],answer:0,explain:"Sekali sesuatu tersebar (di-screenshot, dibagikan ulang), menghapus dari akun asalmu tidak menghapus semua salinannya.",hint:"Bisa disalin & tersebar ke banyak tempat, atau otomatis hilang?"},
{n:5,type:"mcq",micro:"Siapa yang bisa melihat",q:"Sebelum memposting sesuatu, penting mempertimbangkan siapa saja yang mungkin melihatnya karena...",options:["Tidak ada yang benar-benar memperhatikan unggahan orang lain, jadi tidak perlu memikirkan siapa yang melihatnya","Audiens bisa lebih luas dari yang kamu duga: teman-dari-teman, orang asing, bahkan orang di masa depan (guru, calon atasan)","Hanya orang yang kamu tandai atau kamu sebut namanya yang bisa melihat unggahanmu, tidak ada orang lain"],answer:1,explain:"Pengaturan privasi bisa bocor, tangkapan layar bisa disebar, & unggahan publik bisa ditemukan siapa saja kapan saja.",hint:"Audiens bisa lebih luas dari dugaan, atau hanya yang ditandai?"},
{n:6,type:"mcq",micro:"Privasi",q:"'Privasi' dalam konteks digital berarti...",options:["Menyembunyikan diri sepenuhnya dari internet dan tidak pernah memakai layanan digital apa pun juga","Sesuatu yang tidak relevan bagi anak-anak, karena hanya orang dewasa yang punya informasi pribadi","Kendali atas siapa yang bisa melihat/mengakses informasimu, & informasi apa yang kamu bagikan"],answer:2,explain:"Privasi bukan berarti tidak pernah online, melainkan punya kendali & kesadaran atas apa yang dibagikan & kepada siapa.",hint:"Kendali atas berbagi, atau menyembunyikan diri total?"},
{n:7,type:"mcq",micro:"Geotagging",q:"'Geotagging' (menandai lokasi) pada foto/unggahan berarti...",options:["Menyertakan info lokasi tempat foto/unggahan dibuat, kadang otomatis tanpa disadari","Menandai orang di dalam foto","Mengubah warna foto"],answer:0,explain:"Banyak kamera & aplikasi menyimpan lokasi secara otomatis. Ini bisa mengungkap di mana kamu berada, kadang secara langsung/waktu nyata.",hint:"Info lokasi otomatis, atau menandai orang?"},
{n:8,type:"mcq",micro:"Data yang dikumpulkan aplikasi",q:"Aplikasi gratis sering mengumpulkan data seperti...",options:["Hanya nama pengguna","Kebiasaan pemakaian, lokasi, kontak, & minat, untuk ditampilkan iklan atau dijual ke pihak lain","Tidak mengumpulkan data apa pun"],answer:1,explain:"Memahami bahwa 'gratis' sering dibayar dengan datamu membantu kita lebih sadar apa yang kita berikan.",hint:"Banyak jenis data, atau tidak ada sama sekali?"},
{n:9,type:"order",micro:"Alur sebuah unggahan",q:"Urutkan yang terjadi setelah kamu memposting sesuatu secara publik.",items:["Unggahan tersimpan di server platform","Siapa pun (sesuai pengaturan) bisa melihat, menyukai, atau membagikannya","Orang lain bisa menyimpan tangkapan layar atau membagikan ulang","Salinan unggahan bisa ada di banyak tempat, di luar kendalimu"],answer:[0,1,2,3],explain:"Simpan di server → terlihat orang → disalin/dibagikan → tersebar di luar kendali. Inilah kenapa 'menghapus' tidak selalu berarti hilang total.",hint:"Penyebaran salinan terjadi sebelum atau sesudah orang lain melihatnya?"},
{n:10,type:"mcq",micro:"Berpikir sebelum posting",q:"Aturan sederhana sebelum memposting sesuatu:",options:["Posting dulu secepatnya, pikirkan nanti kalau ada yang protes atau menyuruhmu menghapusnya","Yang penting terlihat seru dan banyak yang suka sekarang, tak usah memikirkan siapa yang melihat","Bayangkan orang tua, guru, atau orang asing melihatnya, apakah kamu tetap nyaman?"],answer:2,explain:"Membayangkan audiens yang lebih luas & lebih lama (termasuk masa depan) membantu menilai apakah sesuatu pantas dibagikan.",hint:"Bayangkan audiens luas & nyaman atau tidak, atau posting dulu pikir nanti?"},
{n:11,type:"tf",micro:"Semua orang punya jejak digital",q:"Benar atau Salah: Hampir semua orang yang memakai internet (bahkan tanpa media sosial) memiliki jejak digital dalam bentuk tertentu.",answer:true,explain:"Bahkan sekadar mencari sesuatu di mesin pencari atau memakai aplikasi peta meninggalkan data.",hint:"Hampir semua pengguna internet, atau hanya pengguna media sosial?"},
{n:12,type:"tf",micro:"Mode penyamaran menghapus semua jejak?",q:"Benar atau Salah: Mode 'penyamaran' (incognito/private) di browser membuatmu sepenuhnya tak terlihat & tidak meninggalkan jejak apa pun di internet.",answer:false,explain:"Sebaliknya, mode penyamaran hanya mencegah riwayat tersimpan DI PERANGKATMU. Situs, jaringan, & sekolah/kantor masih bisa melihat aktivitasmu.",hint:"Menghapus semua jejak, atau hanya menyembunyikan riwayat lokal?"},
{n:13,type:"mcq",micro:"Jejak digital & identitas",q:"Kumpulan jejak digitalmu bisa membentuk...",options:["Gambaran (kadang tidak lengkap atau salah) tentang siapa dirimu di mata orang lain, termasuk orang yang belum pernah bertemu kamu","Tidak membentuk apa-apa sama sekali di mata siapa pun, karena jejak digital hanyalah kumpulan data acak yang tidak punya arti bagi orang lain","Hanya dilihat dan dipahami oleh dirimu sendiri, karena tidak ada orang lain yang bisa menemukan, membaca, atau menafsirkan jejak digitalmu"],answer:0,explain:"Orang lain (termasuk calon sekolah/pekerjaan) sering mencari nama seseorang & menyimpulkan sesuatu dari yang mereka temukan.",hint:"Membentuk gambaran di mata orang lain, atau tidak membentuk apa-apa?"},
{n:14,type:"mcq",micro:"Membedakan yang dibagikan",q:"Sebelum membagikan sesuatu, berguna membedakan info yang...",options:["Tidak ada bedanya, karena semua informasi punya tingkat kerahasiaan yang sama di mata orang lain","Aman dibagikan luas, hanya untuk teman dekat, atau sebaiknya tidak dibagikan sama sekali","Boleh dibagikan ke banyak orang, termasuk alamat rumah, nomor telepon, dan jadwal harian"],answer:1,explain:"Tidak semua info sama tingkat sensitifnya. Alamat rumah beda dengan foto liburan yang sudah lewat, misalnya.",hint:"Ada tingkatan kelayakan berbagi, atau semua sama?"},
{n:15,type:"mcq",micro:"Jejak digital orang lain",q:"Memposting foto/video orang lain tanpa izin mereka berarti...",options:["Tidak masalah karena kamu yang mengambil fotonya, sehingga kamu bebas memakainya sesukamu tanpa bertanya","Diperbolehkan asalkan untuk teman sendiri, walaupun orang di foto itu tidak nyaman atau tidak setuju","Ikut membentuk jejak digital mereka tanpa persetujuan mereka, yang bisa merugikan atau membuat tidak nyaman"],answer:2,explain:"Jejak digital bukan hanya tentang diri sendiri. Menghormati privasi orang lain berarti mempertimbangkan izin sebelum memposting mereka.",hint:"Membentuk jejak mereka tanpa izin, atau bebas karena kamu yang memfoto?"},
{n:16,type:"tf",micro:"Jejak digital bisa positif",q:"Benar atau Salah: Jejak digital selalu berbahaya & tidak pernah bisa membangun sesuatu yang positif tentang dirimu.",answer:false,explain:"Sebaliknya, jejak digital adalah alat, bukan musuh. Unggahan yang menunjukkan prestasi, karya, atau kebaikan bisa membangun reputasi digital yang positif bila dikelola dengan sadar.",hint:"Bisa membangun reputasi positif, atau selalu berbahaya?"},
{n:17,type:"mcq",micro:"Cookie",q:"'Cookie' pada situs web adalah...",options:["Potongan data kecil yang disimpan browser untuk mengingat aktivitasmu di situs itu (mis. keranjang belanja, login)","Kue sungguhan yang dikirim lewat internet","Virus komputer"],answer:0,explain:"Cookie berguna (mengingat login) tapi juga dipakai untuk melacak kebiasaan browsingmu di berbagai situs untuk iklan.",hint:"Data kecil untuk mengingat aktivitas, atau kue sungguhan?"},
{n:18,type:"mcq",micro:"Iklan yang 'mengikuti'",q:"Kenapa kadang iklan tentang sesuatu yang baru saja kamu cari muncul di situs lain?",options:["Situs itu bisa membaca pikiranmu lewat kamera dan mikrofon, sehingga tahu apa yang sedang kamu inginkan","Data pencarian/kunjunganmu dipakai untuk menargetkan iklan lewat pelacakan lintas situs","Kebetulan semata tanpa penjelasan apa pun, karena iklan dipilih secara acak oleh komputer dari daftar besar"],answer:1,explain:"Ini hasil pelacakan (cookie, data perilaku) yang menghubungkan aktivitasmu di berbagai tempat untuk menyasar iklan.",hint:"Hasil pelacakan data, atau membaca pikiran?"},
{n:19,type:"mcq",micro:"Jejak digital & waktu",q:"Sesuatu yang kamu posting hari ini bisa...",options:["Otomatis terhapus dalam sebulan karena internet membersihkan dirinya sendiri secara berkala tanpa diminta","Hanya dilihat pada hari itu saja, sebab setelah itu tidak ada lagi orang yang bisa menemukannya","Masih ditemukan & dilihat bertahun-tahun kemudian, bahkan setelah kamu berubah atau melupakannya"],answer:2,explain:"Internet punya 'ingatan' panjang. Konteks & dirimu bisa berubah, tapi unggahan lama bisa tetap ditemukan.",hint:"Bisa ditemukan bertahun-tahun kemudian, atau otomatis hilang?"},
{n:20,type:"open",micro:"Petakan jejak digitalmu",q:"Buat daftar sederhana jejak digitalmu: (a) 3 jenis jejak AKTIF (yang kamu buat sengaja), (b) 3 jenis jejak PASIF (yang terkumpul tanpa kamu sadari langsung), (c) satu hal dalam daftar itu yang membuatmu berpikir 'oh, aku tidak sadar itu juga jejak digital', (d) satu perubahan kecil yang akan kamu lakukan setelah menyadarinya.",explain:"Jawaban baik: 3+3 contoh yang benar-benar berbeda & sesuai kategorinya (aktif = disengaja, pasif = tanpa sadar langsung), satu momen kesadaran yang jujur & spesifik (bukan generik), & satu perubahan kecil yang benar-benar bisa dilakukan.",hint:"Untuk jejak pasif, pikirkan hal yang tercatat 'di belakang layar' tanpa kamu menekan tombol 'kirim' atau 'posting'.",sample:"(a) Jejak aktif: komentar di video yang kutonton, foto yang kuunggah di media sosial, pesan di grup chat kelas. (b) Jejak pasif: riwayat pencarian di mesin pencari, lokasi yang tercatat aplikasi peta saat kubuka, daftar aplikasi & lama pemakaiannya yang tercatat di pengaturan HP. (c) Yang membuatku sadar: aku baru sadar aplikasi peta mencatat ke mana saja aku pergi meski aku tidak pernah 'mengunggah' lokasi itu ke mana pun, itu tetap tersimpan & bisa membentuk pola tentang kebiasaanku. (d) Perubahan kecil: aku akan memeriksa pengaturan riwayat lokasi di HP-ku & mematikan pelacakan latar belakang untuk aplikasi yang tidak benar-benar butuh tahu lokasiku terus-menerus (mis. aplikasi permainan), sambil membiarkan aplikasi peta tetap tahu lokasi hanya saat sedang kubuka."},
{n:21,type:"classify",micro:"Aman dibagikan luas vs sebaiknya tidak",q:"Kelompokkan tiap info ke 'Umumnya aman dibagikan' atau 'Sebaiknya tidak dibagikan luas'.",items:["Foto liburan yang lokasinya sudah kamu tinggalkan","Alamat rumah lengkap & jadwal harianmu","Pendapat tentang film yang baru ditonton","Nomor kartu pelajar atau nomor identitas resmi"],groups:["Umumnya aman dibagikan","Sebaiknya tidak dibagikan luas"],answer:{"Umumnya aman dibagikan":["Foto liburan yang lokasinya sudah kamu tinggalkan","Pendapat tentang film yang baru ditonton"],"Sebaiknya tidak dibagikan luas":["Alamat rumah lengkap & jadwal harianmu","Nomor kartu pelajar atau nomor identitas resmi"]},explain:"Aman: opini biasa, info yang tidak mengungkap posisi/identitas sensitif saat ini. Sebaiknya tidak: yang bisa dipakai melacak atau meniru identitasmu.",hint:"Bisa dipakai melacak/meniru, atau sekadar opini biasa?"},
{n:22,type:"mcq",micro:"Pengaturan privasi",q:"Memeriksa & mengatur 'pengaturan privasi' akun media sosial berguna untuk...",options:["Mengendalikan siapa yang bisa melihat unggahan, profil, & info pribadimu","Membuat akun lebih cepat dan hemat kuota, tanpa mengubah siapa yang melihat isinya","Menghapus akunmu dari internet beserta kiriman dan data yang pernah kamu simpan di sana"],answer:0,explain:"Sebagian besar platform punya opsi 'siapa yang bisa melihat ini' (publik/teman/khusus). Memeriksanya secara berkala penting.",hint:"Mengendalikan audiens, atau mempercepat akun?"},
{n:23,type:"mcq",micro:"Profil publik vs privat",q:"Beda profil 'publik' dengan 'privat/terkunci':",options:["Privat berarti tidak bisa dilihat siapa pun termasuk dirimu","Publik bisa dilihat siapa saja; privat hanya bisa dilihat oleh yang kamu setujui (mis. pengikut yang diterima)","Keduanya sama saja"],answer:1,explain:"Profil privat menambah lapisan kendali: kamu memilih siapa yang boleh melihat, bukan otomatis semua orang.",hint:"Publik = siapa saja, privat = yang disetujui, atau sama saja?"},
{n:24,type:"mcq",micro:"Menandai lokasi waktu nyata",q:"Menandai lokasimu SAAT INI secara publik (bukan setelah pulang) berisiko karena...",options:["Tidak berisiko sama sekali karena semua pengikutmu pasti orang baik dan tidak ada yang berniat buruk","Membuat baterai HP lebih awet karena fitur lokasi yang aktif menghemat daya dibanding saat dimatikan","Memberi tahu orang lain (termasuk yang tidak dikenal) bahwa kamu ada di sana sekarang & rumahmu mungkin kosong"],answer:2,explain:"Info lokasi waktu nyata yang publik bisa dipakai untuk mengetahui pola & keberadaanmu oleh orang yang berniat buruk.",hint:"Mengungkap keberadaan saat ini, atau tidak berisiko?"},
{n:25,type:"mcq",micro:"Jejak digital & pencarian nama",q:"Mencari namamu sendiri di mesin pencari sesekali berguna untuk...",options:["Melihat apa yang orang lain bisa temukan tentangmu & mengelola bila ada yang tidak pantas","Tidak ada gunanya sama sekali, sebab mesin pencari tidak pernah menampilkan informasi tentang orang biasa","Meningkatkan popularitasmu, karena makin sering namamu dicari maka makin banyak orang yang akan menyukaimu"],answer:0,explain:"Ini cara sederhana 'melihat dirimu dari luar' & menemukan info yang mungkin perlu diminta dihapus atau disembunyikan.",hint:"Melihat apa yang bisa ditemukan orang lain, atau tak berguna?"},
{n:26,type:"mcq",micro:"Berbagi dengan teman vs publik",q:"Membagikan sesuatu 'hanya untuk teman' lebih aman daripada publik, TAPI tetap perlu diingat bahwa...",options:["Itu sama amannya dengan tidak memposting sama sekali, jadi tidak ada risiko yang tersisa","Teman bisa membagikan ulang atau menangkap layar ke orang lain di luar kendalimu","Teman tidak bisa membagikan ulang atau menangkap layar, sehingga unggahan itu tetap tersimpan rapat"],answer:1,explain:"Batasan audiens mengurangi risiko, tapi tidak menghilangkannya sepenuhnya. Apa pun yang dibagikan tetap bisa menyebar.",hint:"Tetap bisa disebar teman, atau tidak pernah bisa / sepenuhnya aman?"},
{n:27,type:"tf",micro:"Nama pengguna anonim",q:"Benar atau Salah: Memakai nama pengguna yang tidak memuat nama asli membuatmu sepenuhnya anonim & tidak bisa dilacak sama sekali.",answer:false,explain:"Sebaliknya, kombinasi info lain (foto, tulisan, kebiasaan, lokasi yang disebut) sering tetap bisa mengarah balik ke identitasmu meski nama penggunanya samaran.",hint:"Sepenuhnya anonim, atau tetap bisa terlacak dari info lain?"},
{n:28,type:"tf",micro:"Berbagi berlebihan (oversharing)",q:"Benar atau Salah: Membagikan info secara berlebihan (jadwal harian lengkap, detail masalah keluarga secara publik) selalu aman selama diunggah dengan niat baik.",answer:false,explain:"Sebaliknya, itu disebut 'oversharing' & bisa berisiko, karena melampaui apa yang benar-benar perlu diketahui audiensnya. Tidak semua orang perlu tahu semuanya.",hint:"Berlebihan melampaui kebutuhan & berisiko, atau selalu aman?"},
{n:29,type:"mcq",micro:"Aplikasi yang meminta lokasi terus-menerus",q:"Aplikasi senter yang meminta izin lokasi 'selalu aktif' patut dicurigai karena...",options:["Semua aplikasi memang selalu butuh lokasi untuk berfungsi dengan benar, termasuk senter, kalkulator, dan jam","Itu wajar saja dan tidak perlu dipikirkan, sebab izin yang diminta aplikasi selalu pasti sesuai dengan fungsinya","Fungsinya tidak butuh lokasi sama sekali; permintaan berlebihan mungkin untuk mengumpulkan data, bukan fungsi"],answer:2,explain:"Cocokkan izin dengan fungsi. Permintaan yang tidak masuk akal adalah tanda bahaya untuk privasi.",hint:"Tidak sesuai fungsi = curiga, atau semua aplikasi wajar minta lokasi?"},
{n:30,type:"order",micro:"Sebelum memposting foto bersama teman",q:"Urutkan langkah yang baik sebelum memposting foto yang ada teman di dalamnya.",items:["Tanya apakah temanmu nyaman fotonya diposting","Periksa apakah ada info sensitif tak sengaja terlihat di foto (alamat, dokumen, dll)","Pertimbangkan pengaturan audiens yang sesuai","Posting, & hapus/edit bila kemudian temanmu keberatan"],answer:[0,1,2,3],explain:"Minta izin → cek info sensitif → atur audiens → posting & tetap responsif pada keberatan. Izin datang paling awal.",hint:"Meminta izin sebelum atau sesudah memposting?"},
{n:31,type:"mcq",micro:"Data yang dikumpulkan sekolah/aplikasi belajar",q:"Aplikasi belajar daring sekolah biasanya mengumpulkan data seperti nilai & kehadiran. Sikap yang wajar:",options:["Wajar untuk tujuan pendidikan, tapi tetap layak tahu siapa yang mengakses & bagaimana data itu dijaga","Menolak semua aplikasi sekolah tanpa melihat tujuannya, karena data dari sekolah dianggap berbahaya","Tak perlu dipikirkan, sebab data sekolah otomatis aman dan tidak mungkin diakses pihak yang tidak berhak"],answer:0,explain:"Konteks pendidikan sering butuh data tertentu secara sah, tapi kesadaran & pertanyaan yang wajar tetap sehat.",hint:"Wajar tapi tetap sadar & bertanya, atau menolak semua / tak peduli?"},
{n:32,type:"tf",micro:"Menghapus unggahan mengurangi jejak",q:"Benar atau Salah: Menghapus sebuah unggahan menjamin semua salinannya (screenshot, dibagikan ulang) ikut terhapus dari internet.",answer:false,explain:"Sebaliknya, menghapus tetap langkah baik & mengurangi jejak ke depan, tapi realistis: begitu sesuatu terlihat orang, sepenuhnya menghapusnya dari 'internet' sering tidak mungkin.",hint:"Mengurangi tapi tak menjamin hilang total, atau menghapus semua sisa?"},
{n:33,type:"mcq",micro:"Membaca kebijakan privasi",q:"Kebijakan privasi sebuah layanan menjelaskan...",options:["Harga berlangganan","Data apa yang dikumpulkan, untuk apa dipakai, & dengan siapa dibagikan","Cara menggunakan fitur aplikasi"],answer:1,explain:"Meski sering panjang & sulit dibaca, kebijakan privasi adalah tempat resmi mencari tahu bagaimana datamu diperlakukan.",hint:"Penjelasan pemakaian data, atau cara pakai fitur?"},
{n:34,type:"mcq",micro:"Berpikir tentang audiens masa depan",q:"'Bagaimana ini terlihat 5 tahun lagi, bagi calon sekolah/atasan?' adalah pertanyaan yang membantu karena...",options:["Tidak relevan, karena masa depan tidak bisa diprediksi dan unggahan lama jarang dilihat lagi oleh orang","Hanya berlaku untuk orang dewasa yang melamar kerja, sedangkan anak-anak belum perlu memikirkannya","Nilai & konteks berubah; sesuatu yang lucu sekarang bisa terasa memalukan atau disalahpahami nanti"],answer:2,explain:"Standar yang berlaku sekarang bisa berubah, & audiens di masa depan mungkin menilai berbeda dari teman-temanmu sekarang.",hint:"Konteks & nilai bisa berubah, atau tidak relevan?"},
{n:35,type:"mcq",micro:"Membatasi jejak tanpa menghindari internet total",q:"Cara realistis mengelola jejak digital:",options:["Sadar & selektif: pikirkan sebelum berbagi, atur privasi, & pahami apa yang dikumpulkan, bukan menghindari internet sepenuhnya","Berhenti memakai internet sepenuhnya supaya tidak punya jejak digital, termasuk untuk belajar dan berkomunikasi","Membagikan semuanya tanpa berpikir, karena jejak digital tidak bisa dihindari dan tidak ada gunanya diatur"],answer:0,explain:"Menghindari internet sepenuhnya tidak realistis & kehilangan manfaatnya. Kesadaran & kendali yang selektif adalah jalan tengah yang sehat.",hint:"Sadar & selektif, atau hindari total / abai total?"},
{n:36,type:"mcq",micro:"Jejak digital & rekam jejak pencarian",q:"Riwayat pencarianmu bisa mengungkap...",options:["Hanya kata-kata acak tanpa makna, karena mesin pencari mencatat huruf tanpa memahami maksudmu","Minat, kekhawatiran, & pertanyaan pribadimu, meski kamu tidak pernah membagikannya ke siapa pun","Tidak mengungkap apa-apa tentang dirimu, sebab riwayat pencarian tidak disimpan atau dilihat pihak lain"],answer:1,explain:"Pola pencarian sering sangat pribadi & mengungkap banyak hal, karena itu berguna dipahami sebagai bagian dari jejak digital.",hint:"Mengungkap minat & kekhawatiran, atau tak bermakna?"},
{n:37,type:"tf",micro:"Berbagi lokasi dengan keluarga berbeda dari publik",q:"Benar atau Salah: Membagikan lokasi secara privat dengan keluarga untuk keamanan sama risikonya dengan menandai lokasi secara publik ke semua orang.",answer:false,explain:"Sebaliknya, konteks & audiens menentukan risikonya. Berbagi terbatas dengan orang tepercaya untuk tujuan keamanan berbeda dari mengumumkan ke publik.",hint:"Konteks & audiens berbeda tingkat risikonya, atau sama saja?"},
{n:38,type:"mcq",micro:"Jejak digital yang dibuat orang lain",q:"Selain yang kamu buat sendiri, jejak digital tentang dirimu juga bisa dibuat oleh...",options:["Hanya dirimu sendiri, sebab orang lain tidak bisa memotret atau menandai kamu di internet","Tidak mungkin orang lain, karena data tentangmu hanya muncul kalau kamu yang mengunggahnya langsung","Orang lain yang menandaimu, memfotomu, atau menyebut namamu di unggahan mereka"],answer:2,explain:"Kamu tidak sepenuhnya mengendalikan jejak digitalmu sendirian; orang lain juga berkontribusi, sengaja atau tidak.",hint:"Bisa dibuat orang lain juga, atau hanya oleh dirimu?"},
{n:39,type:"mcq",micro:"Menghapus tag/tandaan",q:"Kalau seseorang menandaimu di sebuah unggahan yang membuatmu tidak nyaman, langkah yang bisa dilakukan:",options:["Minta mereka menghapusnya, atau lepaskan tandamu (untag) & atur agar unggahan bertanda perlu persetujuanmu","Diamkan saja karena tidak bisa dilakukan apa-apa, sebab setiap unggahan yang sudah terkirim tidak akan bisa diubah lagi","Marah di kolom komentar dan membalas dengan kasar tanpa mengambil tindakan lain yang sebenarnya tersedia di pengaturan"],answer:0,explain:"Banyak platform punya opsi melepas tanda atau meninjau tanda sebelum muncul di profilmu. Memakai fitur ini adalah bentuk menjaga jejakmu.",hint:"Minta hapus/lepas tanda, atau diamkan / marah tanpa tindakan?"},
{n:40,type:"open",micro:"Nilai risiko sebuah unggahan",q:"Bayangkan kamu ingin memposting: foto sedang di rumah sendirian (jadwal orang tua terlihat di kalender belakang), dengan lokasi waktu nyata ditandai, dibagikan ke publik. Analisis: (a) minimal 3 risiko dari unggahan ini, (b) 3 perubahan yang akan membuatnya lebih aman tanpa kehilangan makna berbagi momennya, (c) siapa yang menurutmu paling perlu diajak bicara sebelum memposting hal seperti ini.",explain:"Jawaban baik: 3 risiko yang spesifik & masuk akal (bukan generik 'berbahaya'), 3 perubahan konkret yang benar-benar mengurangi risiko sambil tetap membiarkan berbagi terjadi, & identifikasi pihak yang tepat untuk diajak bicara dengan alasan yang jelas.",hint:"Perhatikan tiga hal sekaligus dalam skenario: waktu nyata, latar belakang yang bocor info, & audiens publik. Tiap satu adalah risiko terpisah.",sample:"(a) Risiko: (1) Menandai lokasi waktu nyata memberi tahu orang bahwa aku sendirian di rumah sekarang, yang berisiko bagi keselamatan. (2) Kalender di latar belakang bisa mengungkap jadwal orang tua, informasi yang tidak seharusnya diketahui orang asing. (3) Dibagikan ke publik berarti siapa pun, termasuk orang yang tidak kukenal, bisa melihat & menyimpan info ini. (b) Perubahan: (1) Posting setelah aku sudah pergi dari rumah/tidak lagi sendirian, bukan waktu nyata. (2) Hapus atau kaburkan bagian kalender sebelum memposting, atau ambil ulang fotonya tanpa latar itu terlihat. (3) Ubah audiens jadi 'hanya teman' bukan publik, & lepas tanda lokasi spesifik, cukup sebut 'di rumah' tanpa detail. (c) Yang perlu diajak bicara: orang tua/waliku, karena unggahan ini menyangkut keamanan rumah & jadwal keluarga, bukan hanya urusanku sendiri."},
{n:41,type:"mcq",micro:"Memeriksa pengaturan privasi berkala",q:"Kebiasaan yang baik terkait pengaturan privasi:",options:["Tidak perlu diatur, karena pengaturan bawaan platform sudah paling aman untuk semua pengguna","Periksa & sesuaikan secara berkala, karena platform kadang mengubah default-nya tanpa banyak pemberitahuan","Atur sekali saja saat mendaftar dan jangan dicek lagi, karena pengaturan privasi tidak berubah"],answer:1,explain:"Pembaruan aplikasi kadang mengembalikan pengaturan ke 'lebih terbuka'. Memeriksa berkala menjaga kendali tetap sesuai keinginanmu.",hint:"Periksa berkala, atau atur sekali & lupakan?"},
{n:42,type:"mcq",micro:"Menghapus riwayat & data yang tak perlu",q:"Membersihkan riwayat pencarian & lokasi secara berkala berguna untuk...",options:["Membuat internet lebih cepat untuk banyak orang di dunia karena server menjadi lebih lega","Tidak ada manfaatnya, sebab data yang sudah tercatat tidak mungkin dikurangi dengan cara apa pun","Mengurangi jumlah data pribadi yang tersimpan & bisa diakses bila perangkat/akun bermasalah"],answer:2,explain:"Data yang tidak disimpan tidak bisa bocor. Membersihkan yang tidak perlu adalah 'kebersihan digital' yang sehat.",hint:"Mengurangi data yang tersimpan, atau mempercepat internet global?"},
{n:43,type:"mcq",micro:"Menyunting foto sebelum posting",q:"Sebelum memposting foto, memeriksa & mengaburkan info sensitif di latar (papan nama, dokumen, plat nomor) adalah...",options:["Kebiasaan baik untuk mengurangi info yang tidak sengaja terbagikan","Tidak perlu, karena orang jarang memperhatikan detail di latar foto","Hanya perlu untuk orang dewasa, sedangkan foto anak tidak mengandung info sensitif yang bisa disalahgunakan"],answer:0,explain:"Info sensitif sering muncul tanpa disadari di latar foto. Memeriksanya sebentar mencegah kebocoran tak sengaja.",hint:"Periksa & kaburkan info sensitif, atau tak perlu diperhatikan?"},
{n:44,type:"mcq",micro:"Meminta data dihapus",q:"Banyak layanan menyediakan cara meminta akun/data dihapus. Ini berguna ketika...",options:["Hanya berlaku untuk perusahaan besar, sedangkan pengguna biasa tidak berhak meminta datanya dihapus","Kamu sudah tidak memakai layanan itu lagi & tidak ingin datamu terus tersimpan di sana","Harus dilakukan tiap minggu terhadap layanan yang pernah kamu pakai, tanpa melihat apakah masih dipakai"],answer:1,explain:"Akun lama yang ditinggalkan tetap menyimpan datamu selama tidak dihapus. Membersihkannya mengurangi jejak yang tidak lagi berguna.",hint:"Untuk layanan yang sudah tidak dipakai, atau wajib mingguan?"},
{n:45,type:"tf",micro:"Berpikir sebelum mengomentari",q:"Benar atau Salah: Komentar yang kamu tulis di unggahan orang lain bukan bagian dari jejak digitalmu, hanya unggahanmu sendiri yang dihitung.",answer:false,explain:"Sebaliknya, komentar juga tersimpan & terlihat di unggahan orang lain, jadi tetap terhubung ke identitasmu & menjadi bagian dari jejak digitalmu.",hint:"Komentar juga jejak digital, atau hanya unggahan sendiri?"},
{n:46,type:"mcq",micro:"Menyesuaikan audiens per unggahan",q:"Fitur mengatur audiens berbeda untuk tiap unggahan (mis. ini untuk 'teman dekat', itu untuk 'publik') berguna karena...",options:["Membuat prosesnya lebih rumit tanpa manfaat apa pun, sehingga sebaiknya semua unggahan memakai satu pengaturan saja","Semua unggahan sebaiknya selalu publik, karena membatasi audiens berarti kamu menyembunyikan sesuatu yang buruk","Tidak semua yang ingin kamu bagikan cocok untuk semua orang, jadi bisa disesuaikan konteksnya"],answer:2,explain:"Konteks berbeda butuh audiens berbeda. Foto keluarga mungkin untuk kerabat dekat, opini umum mungkin cocok lebih luas.",hint:"Menyesuaikan konteks & audiens, atau selalu publik?"},
{n:47,type:"mcq",micro:"Menjaga jejak digital tetap positif",q:"Cara membangun jejak digital yang lebih positif dari waktu ke waktu:",options:["Sesekali bagikan karya, pencapaian, atau hal baik yang mencerminkan dirimu, selain berhati-hati pada yang berisiko","Hanya fokus menghindari hal buruk saja tanpa membangun atau membagikan hal baik apa pun dari dirimu sendiri","Tidak ada cara membangunnya, jejak digital hanya bisa dijaga agar jangan sampai menjadi buruk"],answer:0,explain:"Selain menghindari risiko, jejak digital bisa dibentuk secara aktif & positif, jadi 'portofolio' alami tentang siapa dirimu.",hint:"Membangun positif secara aktif, atau hanya menghindari yang buruk?"},
{n:48,type:"mcq",micro:"Menilai permintaan pertemanan/pengikut tak dikenal",q:"Menerima permintaan pertemanan dari akun tidak dikenal secara sembarangan berisiko karena...",options:["Tidak memengaruhi privasimu, karena teman baru tidak bisa melihat yang kamu bagikan di akunmu","Memberi mereka akses ke info yang kamu bagikan hanya untuk 'teman', tanpa kamu benar-benar tahu siapa mereka","Aman karena hanya menambah jumlah teman, dan makin banyak teman daring berarti makin aman bagimu"],answer:1,explain:"'Hanya untuk teman' hanya seaman orang-orang yang kamu terima sebagai teman. Menerima sembarangan melemahkan batas itu.",hint:"Memberi akses ke orang tak dikenal, atau selalu aman?"},
{n:49,type:"mcq",micro:"Jejak digital di aplikasi belajar/permainan",q:"Saat mendaftar aplikasi belajar atau game baru, kebiasaan yang bijak:",options:["Isi semua kolom termasuk yang opsional dengan info asli, supaya akunmu lengkap dan layanannya makin bagus buatmu","Selalu memakai info palsu untuk semua kolom termasuk yang wajib dan sah, sehingga akun pasti tidak bisa dipakai","Isi hanya info yang benar-benar diwajibkan, & periksa apakah ada opsi membatasi data yang dibagikan ke pihak ketiga"],answer:2,explain:"Mengisi seperlunya (bukan berlebihan, bukan berbohong pada yang memang perlu sah) menyeimbangkan fungsi & privasi.",hint:"Isi seperlunya & batasi berbagi ke pihak ketiga, atau isi semua / palsukan semua?"},
{n:50,type:"order",micro:"Membersihkan jejak digital lama",q:"Urutkan langkah 'bersih-bersih' jejak digital sederhana.",items:["Cari namamu di mesin pencari & lihat apa yang muncul","Tinjau akun-akun lama yang sudah tidak dipakai","Hapus atau perbarui unggahan lama yang sudah tidak sesuai dirimu sekarang","Perbarui pengaturan privasi akun yang masih aktif"],answer:[0,1,2,3],explain:"Lihat gambaran saat ini → tinjau akun lama → bersihkan unggahan lama → kuatkan pengaturan yang masih dipakai. Dari melihat ke membersihkan ke mengunci.",hint:"Meninjau akun lama sebelum atau sesudah mencari namamu di mesin pencari?"},
{n:51,type:"mcq",micro:"Menjaga privasi saat kolaborasi daring",q:"Saat mengerjakan proyek kelompok daring dengan orang yang belum kamu kenal baik, kebiasaan yang bijak:",options:["Bagikan info secukupnya untuk kerja sama (nama, cara menghubungi lewat kanal proyek), tanpa perlu berbagi akun pribadi atau info sangat personal","Bagikan semua akun media sosial pribadimu kepada mereka agar lebih akrab dan cepat saling percaya, tanpa perlu memikirkan siapa mereka sebenarnya dan apa tujuan mereka","Tolak semua kolaborasi daring dengan siapa pun yang belum kamu kenal baik, dan kerjakan seluruh proyek sendirian saja tanpa bantuan dari teman satu kelompok"],answer:0,explain:"Kerja sama tidak butuh berbagi seluruh kehidupan pribadi. Menjaga batas yang wajar tetap memungkinkan kolaborasi baik.",hint:"Bagikan secukupnya untuk kerja, atau semua akun pribadi / tolak semua?"},
{n:52,type:"tf",micro:"Foto lama tetap relevan diperiksa",q:"Benar atau Salah: Unggahan dari bertahun-tahun lalu tidak perlu pernah ditinjau ulang karena standar & kenyamananmu tidak akan berubah.",answer:false,explain:"Sebaliknya, yang terasa wajar di masa lalu bisa terasa tidak lagi mewakili dirimu sekarang. Meninjau ulang & membersihkan unggahan lama secara berkala itu wajar.",hint:"Layak ditinjau ulang, atau biarkan selamanya tanpa dicek?"},
{n:53,type:"mcq",micro:"Menjaga privasi lokasi rutin",q:"Membagikan bahwa kamu 'selalu di kafe X tiap Sabtu jam 3' secara publik berisiko karena...",options:["Hanya berisiko kalau disebutkan sekali, tetapi bila diulang justru tidak jadi masalah","Membentuk pola yang bisa dipakai untuk mengetahui & memprediksi keberadaanmu","Tidak ada risiko, itu kebiasaan biasa dan tidak mungkin dimanfaatkan orang yang tidak dikenal"],answer:1,explain:"Pola rutin yang terlihat publik lebih berisiko daripada info sekali, karena bisa diandalkan untuk merencanakan sesuatu terhadapmu.",hint:"Membentuk pola yang bisa diprediksi, atau tak berisiko?"},
{n:54,type:"mcq",micro:"Data biometrik & privasi",q:"Data seperti sidik jari & wajah (biometrik) perlu perlakuan ekstra hati-hati karena...",options:["Sama saja dengan data lain, tidak perlu perhatian khusus, dan bisa diganti mudah bila bocor","Tidak dikumpulkan oleh aplikasi mana pun, sehingga tidak perlu berhati-hati menyerahkannya","Tidak bisa 'diganti' seperti kata sandi bila bocor, ia melekat pada dirimu seumur hidup"],answer:2,explain:"Kata sandi bisa diganti; sidik jari & wajahmu tidak. Karena itu perlindungannya perlu lebih serius.",hint:"Tak bisa diganti bila bocor, atau sama saja dengan data lain?"},
{n:55,type:"mcq",micro:"Jejak digital & aplikasi pihak ketiga",q:"Menghubungkan akun media sosialmu ke aplikasi/kuis pihak ketiga ('cek kepribadianmu!') berisiko karena...",options:["Aplikasi itu bisa mendapat akses ke data profilmu & teman-temanmu, kadang lebih dari yang kamu sadari","Tidak ada risiko, itu hanya hiburan, dan aplikasi kuis tidak mengumpulkan data dari profilmu","Memperkuat keamanan akunmu, karena akses pihak ketiga biasanya menambah lapisan perlindungan"],answer:0,explain:"Kuis & aplikasi pihak ketiga sering dipakai untuk mengumpulkan data secara luas dengan kedok hiburan. Periksa izin sebelum menghubungkan akun.",hint:"Bisa mengakses data lebih dari disadari, atau hanya hiburan tanpa risiko?"},
{n:56,type:"tf",micro:"Anak-anak juga punya hak privasi",q:"Benar atau Salah: Privasi hanya berlaku & relevan untuk orang dewasa, bukan untuk anak-anak & remaja.",answer:false,explain:"Sebaliknya, anak-anak & remaja juga berhak atas privasi & kendali yang wajar atas informasi pribadi mereka, sesuai usia & kemampuan mereka memahami risikonya.",hint:"Anak-anak juga berhak privasi wajar, atau hanya untuk dewasa?"},
{n:57,type:"mcq",micro:"Menjaga jejak digital saat marah/emosi",q:"Saat sedang sangat marah atau kesal, kebiasaan yang bijak sebelum memposting sesuatu:",options:["Posting dulu lalu langsung hapus akunmu jika kemudian menyesal, sebab menghapus akun pasti menghilangkan semua jejaknya","Tunggu sebentar sampai lebih tenang sebelum memposting, karena unggahan emosional sering disesali kemudian & sulit ditarik kembali","Posting segera selagi emosinya masih terasa asli, karena menunda akan membuat pesanmu tidak jujur dan kurang berpengaruh"],answer:1,explain:"Jeda sebelum memposting mengurangi risiko menyesal karena unggahan yang sudah terlanjur dilihat & disalin orang lain.",hint:"Tunggu tenang dulu, atau posting segera saat emosi?"},
{n:58,type:"mcq",micro:"Membaca ulang sebelum kirim",q:"Kebiasaan membaca ulang pesan/komentar sebelum mengirim membantu karena...",options:["Membuang waktu tanpa manfaat, karena pesan yang sudah ditulis sesuai dengan maksud penulisnya","Tidak memengaruhi cara pesan diterima orang lain, sebab pembaca tahu persis yang kamu maksudkan","Memberi kesempatan menilai apakah nadanya seperti yang dimaksud & tidak akan disalahpahami atau menyakiti"],answer:2,explain:"Teks tanpa nada suara & ekspresi wajah mudah disalahpahami. Membaca ulang sejenak bisa mencegah kesalahpahaman yang tercatat permanen.",hint:"Menilai nada & mencegah salah paham, atau tak berpengaruh?"},
{n:59,type:"mcq",micro:"Berbagi info kesehatan/pribadi sensitif",q:"Info yang sangat pribadi (kesehatan, masalah keluarga, perasaan yang sangat rentan) sebaiknya...",options:["Dipertimbangkan matang-matang audiensnya; sering lebih aman dibagikan ke orang tepercaya langsung daripada di ruang publik luas","Dibagikan secara publik supaya mendapat dukungan dari sebanyak mungkin orang, tanpa memikirkan siapa yang melihat","Dirahasiakan dari siapa pun, sekalipun kamu sedang membutuhkan bantuan dari orang yang kamu percayai"],answer:0,explain:"Dukungan tetap penting & berharga, tapi memilih audiens yang tepat (orang tepercaya) lebih aman daripada publik luas untuk hal yang sangat rentan.",hint:"Pilih audiens tepercaya dengan bijak, atau selalu publik / tak pernah dibagikan?"},
{n:60,type:"open",micro:"Rencana pengelolaan jejak digital",q:"Buat rencana pribadi mengelola jejak digitalmu untuk 3 bulan ke depan. Sertakan: (a) satu kebiasaan yang akan kamu terapkan sebelum memposting, (b) satu tindakan untuk memeriksa/membersihkan jejak lama, (c) satu perubahan pada pengaturan privasi akun tertentu, (d) cara kamu akan menyeimbangkan berbagi (karena tetap ingin terhubung dengan teman) dengan menjaga privasi.",explain:"Jawaban baik: kebiasaan pra-posting yang konkret & bisa diingat, tindakan pembersihan yang spesifik & terjadwal, satu perubahan pengaturan nyata yang disebut dengan jelas, & penjelasan keseimbangan yang menunjukkan pemahaman bahwa privasi bukan berarti berhenti berbagi sama sekali.",hint:"Bagian (d) penting untuk menunjukkan kamu paham privasi bukan 'jangan pernah membagikan apa pun', tapi berbagi dengan sadar.",sample:"(a) Kebiasaan sebelum posting: aku akan bertanya pada diriku 3 hal sebelum memposting apa pun, siapa yang akan melihat ini, apakah ada info sensitif yang tidak sengaja ikut terlihat, & apakah aku masih nyaman dengan ini 2 tahun lagi. (b) Memeriksa jejak lama: bulan pertama, aku akan mencari namaku di mesin pencari & meninjau unggahan publik lamaku di akun utama, menghapus atau mengubah audiens unggahan yang terasa tidak lagi cocok. (c) Perubahan pengaturan: aku akan mengubah profil media sosial utamaku dari publik menjadi hanya bisa dilihat pengikut yang kusetujui, & mematikan berbagi lokasi otomatis di semua aplikasi kecuali peta saat sedang kubuka. (d) Menyeimbangkan: aku tetap akan membagikan momen dengan teman & keluarga lewat grup/audiens terbatas yang kupercaya, sambil lebih selektif soal apa yang kutandai lokasinya & kapan (menandai setelah pulang, bukan waktu nyata); aku juga akan tetap memposting hal-hal positif seperti karya atau pencapaian karena itu membangun jejak yang baik, bukan hanya menghindari yang buruk."},
{n:61,type:"mcq",micro:"Jejak digital & kesempatan masa depan",q:"Semakin banyak sekolah/perusahaan memeriksa jejak digital calon siswa/karyawan. Artinya:",options:["Hanya berlaku untuk orang terkenal, sedangkan siswa biasa jarang diperiksa jejak digitalnya oleh pihak lain","Apa yang kamu bagikan sekarang bisa memengaruhi peluangmu nanti, jadi berpikir jangka panjang itu berguna, bukan menakut-nakuti tanpa alasan","Jejak digital tidak diperiksa oleh pihak mana pun, sehingga kamu bebas memposting apa saja tanpa akibat di kemudian hari"],answer:1,explain:"Ini bukan alasan untuk cemas berlebihan, tapi alasan wajar untuk sedikit lebih sadar & selektif, seperti menjaga sopan santun di depan umum.",hint:"Bisa memengaruhi peluang & wajar dipikirkan, atau tak pernah diperiksa / hanya untuk orang terkenal?"},
{n:62,type:"mcq",micro:"Reputasi digital vs reputasi nyata",q:"Beda & hubungan antara reputasi digital & reputasi 'nyata':",options:["Reputasi digital tidak berhubungan dengan reputasi nyata, karena keduanya ada di dunia yang terpisah","Hanya reputasi nyata yang penting dalam hidup, sedangkan reputasi digital tidak berarti bagi orang lain","Keduanya saling memengaruhi & makin sulit dipisahkan; orang membentuk kesan tentangmu dari keduanya sekaligus"],answer:2,explain:"Di dunia yang makin terhubung, kesan orang tentang kita dibentuk dari gabungan apa yang mereka lihat langsung & apa yang mereka temukan daring.",hint:"Saling memengaruhi, atau sama sekali terpisah?"},
{n:63,type:"mcq",micro:"Algoritma & jejak digital",q:"Platform memakai jejak digitalmu (yang kamu lihat, sukai, cari) untuk...",options:["Menyesuaikan apa yang ditampilkan padamu (rekomendasi, iklan), yang bisa membentuk 'gelembung' info yang sempit","Tidak dipakai untuk keperluan apa pun, hanya disimpan sebagai arsip yang tidak dibuka atau dianalisis platform","Menampilkan hal yang sama kepada setiap orang, sehingga rekomendasi dan iklan tidak disesuaikan"],answer:0,explain:"Algoritma belajar dari jejakmu & menyesuaikan konten. Ini bisa berguna, tapi juga bisa membatasi paparanmu pada sudut pandang lain.",hint:"Membentuk rekomendasi & mungkin 'gelembung' sempit, atau tak dipakai?"},
{n:64,type:"tf",micro:"Kesadaran mengurangi manipulasi",q:"Benar atau Salah: Menyadari bahwa apa yang kamu lihat online dipengaruhi jejak digitalmu sendiri membantu kamu lebih kritis & sengaja mencari sudut pandang lain.",answer:true,explain:"Kesadaran akan 'gelembung filter' adalah langkah pertama untuk secara sengaja mencari info & pandangan yang beragam.",hint:"Membantu lebih kritis & mencari sudut lain, atau tidak berpengaruh?"},
{n:65,type:"mcq",micro:"Jejak digital & belas kasih pada diri sendiri",q:"Kalau di masa lalu kamu pernah memposting sesuatu yang sekarang membuatmu malu, sikap yang sehat:",options:["Berpura-pura itu tidak pernah terjadi dan menyangkalnya setiap kali dibahas, walaupun buktinya jelas","Akui itu bagian dari belajar & tumbuh, perbaiki/hapus bila bisa, & maafkan dirimu, sambil belajar untuk lebih sadar ke depan","Terus menyalahkan diri tanpa henti, sebab satu kesalahan di internet merusak seluruh hidup dan masa depanmu"],answer:1,explain:"Semua orang berubah & belajar. Menyesali secara sehat (perbaiki & maafkan diri) lebih membangun daripada menyalahkan diri terus-menerus.",hint:"Perbaiki, maafkan diri, & belajar, atau menyalahkan diri terus / menyangkal?"},
{n:66,type:"mcq",micro:"Jejak digital sebagai portofolio",q:"Sebagian orang secara sengaja membangun jejak digital positif (blog, karya, portofolio daring) untuk...",options:["Menyembunyikan diri dari internet supaya tidak ada orang yang bisa menemukan kemampuan atau karya mereka","Tidak ada tujuan tertentu, sebab portofolio daring hanya kebiasaan acak yang tak berguna bagi pemiliknya","Menunjukkan keterampilan & minat mereka ke dunia dengan cara yang mereka kendalikan sendiri"],answer:2,explain:"Jejak digital bisa jadi alat proaktif menunjukkan sisi terbaik diri, bukan hanya sesuatu yang perlu dikhawatirkan.",hint:"Menunjukkan diri secara terkendali, atau menyembunyikan diri total?"},
{n:67,type:"mcq",micro:"Menilai risiko secara proporsional",q:"Sikap yang seimbang terhadap privasi digital:",options:["Sadar risiko & mengambil langkah wajar, tanpa jadi sangat cemas hingga menghindari semua interaksi daring","Sama sekali tidak peduli risiko apa pun, karena yang terpenting adalah bebas berbagi tanpa pernah berpikir dua kali lagi","Sangat takut sampai berhenti memakai internet sepenuhnya, bahkan untuk belajar, berkarya, atau berkomunikasi dengan keluarga"],answer:0,explain:"Kewaspadaan yang proporsional (bukan nol, bukan berlebihan) memungkinkan menikmati manfaat digital sambil tetap aman.",hint:"Sadar & wajar, atau tak peduli sama sekali / sangat takut?"},
{n:68,type:"tf",micro:"Jejak digital bisa membantu koneksi baik",q:"Benar atau Salah: Jejak digital yang dikelola baik bisa membantu orang menemukan komunitas, peluang belajar, & hubungan yang positif, bukan hanya membawa risiko.",answer:true,explain:"Sisi positifnya nyata: menemukan komunitas dengan minat sama, peluang, & koneksi bermakna, semua bisa terjadi lewat jejak digital yang dikelola sadar.",hint:"Bisa membawa manfaat positif, atau hanya risiko?"},
{n:69,type:"mcq",micro:"Jejak digital & kejujuran diri",q:"Membangun jejak digital yang 'terlalu sempurna' (hanya menampilkan yang sangat ideal) berisiko...",options:["Tidak berhubungan dengan kesehatan mental, karena tampil sempurna menyenangkan bagi semua orang yang melihatnya","Membuat tekanan pada diri sendiri & orang lain untuk terlihat sempurna terus-menerus, yang tidak realistis & bisa melelahkan","Membawa manfaat tanpa kekurangan, sebab citra yang sempurna membuat orang lain menghormatimu terus"],answer:1,explain:"Perbandingan dengan citra 'sempurna' orang lain (termasuk diri kita yang dikurasi) bisa memengaruhi perasaan tentang diri sendiri.",hint:"Bisa menekan diri & orang lain, atau selalu tanpa kekurangan?"},
{n:70,type:"tf",micro:"Privasi bukan berarti punya sesuatu untuk disembunyikan",q:"Benar atau Salah: Ingin menjaga privasi tidak berarti seseorang punya sesuatu yang buruk untuk disembunyikan; itu tentang menjaga kendali & batas yang wajar.",answer:true,explain:"Argumen 'kalau tidak salah, tidak perlu privasi' keliru. Semua orang, tanpa peduli seberapa 'bersih' hidupnya, berhak menjaga batas & kendali atas info pribadi.",hint:"Tentang kendali & batas wajar, atau berarti ada yang disembunyikan?"},
{n:71,type:"mcq",micro:"Jejak digital & konsekuensi bagi orang lain",q:"Membagikan info tentang keluarga/teman (bukan hanya dirimu) tanpa berpikir bisa...",options:["Hanya memengaruhi dirimu sendiri dan tidak berdampak pada orang lain, karena jejak digital bersifat pribadi","Aman selama kamu sendiri yang memposting, sebab keluarga dan temanmu tidak mungkin keberatan","Membuka risiko bagi mereka juga, bukan hanya dirimu, karena kamu ikut membentuk jejak digital orang lain"],answer:2,explain:"Batas privasi berlaku dua arah: menjaga dirimu & menghormati bahwa orang lain juga punya hak atas info mereka.",hint:"Berisiko juga bagi orang lain, atau hanya bagi dirimu?"},
{n:72,type:"mcq",micro:"Menyeimbangkan keterbukaan & kehati-hatian",q:"Pendekatan yang matang terhadap berbagi di internet:",options:["Terbuka & terhubung, tapi dengan kesadaran, batas, & pilihan yang disengaja, bukan tertutup total atau terbuka tanpa pikir","Tertutup total dan tidak berbagi apa pun kepada siapa pun, termasuk keluarga atau teman dekat di internet","Terbuka total tanpa pertimbangan, karena makin banyak dibagikan makin banyak teman yang datang"],answer:0,explain:"Titik seimbang, bukan dua ekstrem, adalah tujuan literasi privasi yang sehat.",hint:"Terbuka dengan kesadaran & batas, atau salah satu ekstrem?"},
{n:73,type:"mcq",micro:"Jejak digital & identitas yang berkembang",q:"Seiring bertambah usia, minat & nilai-nilai seseorang bisa berubah. Ini penting dipikirkan terkait jejak digital karena...",options:["Jejak digital menyesuaikan diri dengan perubahan diri kita, jadi unggahan lama ikut berubah mengikuti pendapat kita","Sesuatu yang mewakilimu dengan baik sekarang mungkin tidak lagi mewakilimu nanti, jadi meninjau ulang secara berkala itu wajar","Identitas orang tidak berubah sepanjang hidup, sehingga tidak ada alasan meninjau ulang yang pernah dibagikan"],answer:1,explain:"Karena identitas berkembang, jejak digital lama perlu sesekali ditinjau agar tetap relevan atau dihapus bila sudah tidak mewakili.",hint:"Perlu ditinjau ulang seiring perubahan diri, atau tak pernah berubah / otomatis menyesuaikan?"},
{n:74,type:"mcq",micro:"Jejak digital & tekanan kelompok",q:"Ikut memposting/membagikan sesuatu hanya karena semua teman melakukannya, padahal ragu, sebaiknya...",options:["Diikuti saja karena dianggap normal di kelompok, dan menolak berarti kamu tidak setia pada teman","Tak perlu dipikir terlalu jauh, ikuti tren yang sedang ramai supaya kamu tidak terlihat berbeda","Tetap dipertimbangkan sendiri; ikut-ikutan bukan alasan yang cukup kuat untuk mengesampingkan penilaianmu sendiri"],answer:2,explain:"Tekanan kelompok nyata, tapi keputusan tentang jejak digitalmu tetap tanggung jawabmu sendiri, bukan sekadar mengikuti orang lain.",hint:"Tetap pertimbangkan sendiri, atau selalu ikuti kelompok?"},
{n:75,type:"order",micro:"Menanggapi unggahan lama yang bermasalah",q:"Urutkan langkah menanggapi unggahan lamamu yang ternyata bisa disalahpahami atau merugikan.",items:["Baca ulang dengan sudut pandang orang lain, pahami kenapa itu bisa bermasalah","Hapus atau edit unggahan itu bila memungkinkan","Bila sudah tersebar & terlanjur dilihat orang, pertimbangkan klarifikasi singkat & tulus bila perlu","Jadikan pelajaran untuk kebiasaan posting ke depan"],answer:[0,1,2,3],explain:"Pahami masalahnya → hapus/edit → klarifikasi bila perlu → jadikan pelajaran. Memahami dulu sebelum bertindak mencegah reaksi berlebihan atau kurang.",hint:"Menghapus/mengedit sebelum atau sesudah memahami kenapa itu bermasalah?"},
{n:76,type:"tf",micro:"Literasi privasi terus berkembang",q:"Benar atau Salah: Cara platform mengumpulkan & memakai data terus berubah, jadi kebiasaan mengecek pengaturan & memahami hal baru tetap relevan sepanjang waktu, bukan sekali dipelajari lalu selesai.",answer:true,explain:"Teknologi & kebijakan privasi terus berkembang. Sikap belajar berkelanjutan lebih berguna daripada menganggap sudah 'selesai belajar'.",hint:"Perlu terus diperbarui pemahamannya, atau cukup sekali belajar?"},
{n:77,type:"mcq",micro:"Jejak digital & empati pada diri masa depan",q:"Berpikir tentang 'diri di masa depan' saat memposting sesuatu adalah bentuk...",options:["Empati pada diri sendiri, mempertimbangkan perasaan & kepentingan versi dirimu yang akan datang","Hal yang tidak perlu dipikirkan, sebab versi dirimu di masa depan tidak akan peduli pada postinganmu","Cara berpikir yang membuat orang terlalu takut berbagi, sehingga sebaiknya dihindari"],answer:0,explain:"Sama seperti mempertimbangkan perasaan orang lain, mempertimbangkan 'dirimu nanti' adalah bentuk perhatian yang sehat pada diri sendiri.",hint:"Bentuk empati pada diri masa depan, atau tak perlu dipikirkan?"},
{n:78,type:"mcq",micro:"Menilai apakah sesuatu 'terlalu privat' untuk dibagikan",q:"Pertanyaan yang membantu menilai apakah sesuatu terlalu privat untuk dibagikan luas:",options:["'Apakah teman-temanku juga membagikan hal serupa di akun mereka, karena kalau banyak yang melakukannya berarti pasti aman?'","'Apakah ini menyangkut keselamatan, keuangan, atau kehormatan seseorang jika jatuh ke tangan yang salah?'","'Apakah ini terlihat menarik dan akan mendapat banyak suka serta komentar, walaupun menyangkut kehormatan orang lain?'"],answer:1,explain:"Pertanyaan yang fokus pada konsekuensi nyata (keselamatan, keuangan, kehormatan) lebih tajam daripada sekadar 'menarik' atau ikut tren.",hint:"Fokus pada konsekuensi nyata, atau menarik / ikut tren?"},
{n:79,type:"mcq",micro:"Menyadari 'gratis' punya harga tersembunyi",q:"Kesadaran bahwa layanan 'gratis' sering dibiayai dari data pengguna mengubah cara kita...",options:["Berhenti memakai layanan gratis seterusnya, karena yang gratis berbahaya dan merugikan pengguna","Tidak berpengaruh pada keputusan, sebab layanan gratis dan berbayar punya cara kerja yang sama soal data","Menilai apakah pertukaran 'data untuk layanan' itu sepadan bagi kita, bukan menerimanya tanpa pikir"],answer:2,explain:"Bukan berarti semua layanan gratis buruk, tapi kesadaran ini membuat kita memilih dengan lebih sadar apa yang layak ditukar.",hint:"Menilai kesepadanan pertukaran, atau berhenti total / tak berpengaruh?"},
{n:80,type:"open",micro:"Menimbang manfaat & risiko sebuah platform",q:"Pilih satu platform/aplikasi yang kamu pakai rutin. Analisis: (a) manfaat nyata yang kamu dapat darinya, (b) data yang mungkin ia kumpulkan tentangmu, (c) satu pengaturan privasi yang sudah/akan kamu perbaiki di sana, (d) kesimpulan: apakah pertukaran manfaat vs data ini sepadan bagimu, & kenapa.",explain:"Jawaban baik: manfaat yang spesifik & jujur (bukan generik), data yang disebut masuk akal untuk jenis platform itu, satu pengaturan konkret yang benar-benar ada di platform tersebut, & kesimpulan yang menimbang keduanya dengan syarat, bukan jawaban hitam-putih 'baik' atau 'buruk' saja.",hint:"Bagian (d) harus jelas mengambil posisi (sepadan / tidak / sepadan dengan syarat), bukan menggantung tanpa kesimpulan.",sample:"Platform: aplikasi berbagi foto & video pendek yang sering kupakai. (a) Manfaat: terhubung dengan teman, melihat konten kreatif yang menginspirasi, & tempat aku sesekali membagikan karya (foto/edit sederhana) yang kubanggakan. (b) Data yang mungkin dikumpulkan: video yang kutonton & berapa lama, apa yang kusukai/komentari, lokasi (kalau diizinkan), kontak (kalau diizinkan diakses), & pola waktu aku online. Semua ini dipakai untuk menargetkan konten & iklan. (c) Pengaturan yang kuperbaiki: aku akan mengubah akunku jadi privat (hanya pengikut yang kusetujui yang bisa melihat unggahanku), mematikan izin akses kontak & lokasi karena aplikasi ini tidak benar-benar butuh itu untuk fungsi utamanya, & meninjau daftar pengikutku untuk memastikan tidak ada yang tidak kukenal. (d) Kesimpulan: menurutku masih sepadan untuk dipakai, karena manfaat koneksi & kreativitasnya nyata bagiku, TAPI hanya dengan pengaturan privasi yang lebih ketat seperti yang kusebut di atas; kalau tidak ada opsi membatasi seperti itu sama sekali, aku akan mempertimbangkan ulang pemakaiannya."},
{n:81,type:"mcq",micro:"Skenario: teman memposting fotomu tanpa izin",q:"Temanmu memposting foto lucu tapi memalukan dari kamu tanpa bertanya dulu. Langkah yang baik:",options:["Bicarakan langsung dengan baik, jelaskan perasaanmu, & minta dihapus atau audiensnya dibatasi","Diam saja meski tidak nyaman, karena menegur teman akan merusak pertemanan dan tidak ada gunanya","Langsung memposting hal memalukan tentang dia sebagai balasan, supaya kalian impas dan sama-sama merasakan"],answer:0,explain:"Komunikasi langsung & jujur biasanya menyelesaikan hal ini lebih baik daripada diam (menumpuk kekesalan) atau membalas dengan cara yang sama buruknya.",hint:"Bicarakan & minta dihapus, atau diam / balas dengan hal buruk juga?"},
{n:82,type:"mcq",micro:"Skenario: aplikasi baru minta banyak izin",q:"Aplikasi permainan sederhana meminta izin akses kontak, mikrofon, & lokasi. Sikap yang bijak:",options:["Hapus HP-mu karena semua aplikasi terlalu berisiko, lalu berhenti memakai perangkat digital untuk bermain","Tanya apakah izin ini benar-benar dibutuhkan fungsi permainannya; tolak yang tidak masuk akal, atau cari alternatif lain","Setujui semua izin supaya bisa segera bermain tanpa gangguan, sebab permainan hanya butuh izin untuk fungsinya"],answer:1,explain:"Menilai kewajaran izin terhadap fungsi aplikasi adalah kebiasaan dasar melindungi privasi tanpa harus menghindari semua aplikasi.",hint:"Nilai kewajaran izin, atau setujui semua / reaksi berlebihan?"},
{n:83,type:"mcq",micro:"Skenario: orang asing bertanya info pribadi",q:"Seseorang yang baru dikenal daring bertanya alamat rumah & jadwal sekolahmu 'supaya bisa mengirim hadiah'. Sikap yang aman:",options:["Berikan alamat dan jadwal itu karena orang yang menawarkan hadiah terdengar baik hati, dan hadiah gratis tidak mungkin berbahaya","Berikan sebagian info saja, misalnya nama jalan tanpa nomor rumah, sehingga mereka tetap percaya dan kamu tetap merasa aman","Menolak dengan sopan; alasan seperti itu adalah taktik umum yang patut dicurigai, & beri tahu orang dewasa tepercaya"],answer:2,explain:"Permintaan info sensitif dari orang asing daring, apa pun alasannya, adalah tanda bahaya yang perlu ditolak & dilaporkan.",hint:"Tolak & beri tahu dewasa, atau berikan sebagian/seluruhnya?"},
{n:84,type:"mcq",micro:"Skenario: unggahan sekolah menampilkan banyak siswa",q:"Sekolah ingin memposting foto kegiatan yang menampilkan banyak siswa ke media sosial publik sekolah. Pertimbangan yang wajar dari sisi siswa/wali:",options:["Wajar menanyakan kebijakan izin (apakah orang tua bisa memilih anaknya tidak difoto/diposting) & bagaimana data itu dijaga","Tidak perlu dipikirkan, sekolah tentu benar dan tidak mungkin keliru soal privasi murid-muridnya sendiri","Menolak kegiatan sekolah yang melibatkan foto atau video, dan melarang anak ikut acara apa pun"],answer:0,explain:"Institusi yang baik biasanya punya mekanisme izin & pilihan. Menanyakannya adalah hak yang wajar, bukan sikap berlebihan.",hint:"Tanyakan kebijakan izin, atau tak perlu dipikirkan / tolak semua?"},
{n:85,type:"tf",micro:"Kesadaran adalah kekuatan, bukan ketakutan",q:"Benar atau Salah: Memahami jejak digital & privasi bertujuan membuat kita lebih berdaya membuat pilihan, bukan membuat kita takut menggunakan internet.",answer:true,explain:"Tujuan literasi ini adalah kendali & kesadaran, bukan rasa takut yang melumpuhkan. Internet tetap alat yang sangat berharga bila dipakai dengan bijak.",hint:"Membuat berdaya, atau membuat takut?"},
{n:86,type:"mcq",micro:"Skenario: menemukan info palsu tentang diri sendiri",q:"Kamu menemukan seseorang membuat akun palsu memakai namamu & fotomu. Langkah yang tepat:",options:["Diamkan saja karena tidak ada yang bisa dilakukan, akun palsu pasti hilang dengan sendirinya dalam beberapa hari ke depan","Laporkan akun itu ke platform lewat fitur pelaporan resmi, simpan bukti (tangkapan layar), & beri tahu orang dewasa tepercaya","Buat akun palsu balasan memakai nama pelakunya untuk membalas mereka, supaya mereka juga merasakan bagaimana rasanya dirugikan"],answer:1,explain:"Peniruan identitas (impersonation) adalah pelanggaran yang bisa dilaporkan lewat jalur resmi. Bukti & bantuan orang dewasa memperkuat penanganannya.",hint:"Lapor resmi + simpan bukti + beri tahu dewasa, atau balas dengan cara sama / diamkan?"},
{n:87,type:"mcq",micro:"Skenario: memilih platform untuk portofolio",q:"Kamu ingin membangun portofolio karya (gambar/tulisan) secara daring. Pertimbangan privasi yang relevan:",options:["Tampilkan semua info pribadimu, seperti alamat dan sekolah, agar portofoliomu terlihat lebih personal dan lebih dipercaya orang lain","Hindari sepenuhnya membangun portofolio daring karena itu pasti berisiko, dan simpan semua karyamu di buku saja selamanya","Pilih platform yang memberimu kendali atas apa yang publik & apa yang tidak, & pikirkan berapa banyak info pribadi (bukan karya) yang perlu ditampilkan"],answer:2,explain:"Portofolio bisa fokus pada karya tanpa harus mengorbankan info pribadi yang tidak relevan dengan karya itu.",hint:"Kendali audiens + batasi info pribadi tak relevan, atau tampilkan semua / hindari total?"},
{n:88,type:"mcq",micro:"Skenario: grup chat menyebarkan info seseorang",q:"Di grup chat kelas, seseorang membagikan foto pribadi teman lain tanpa izin & menyebar cepat. Sikap yang bertanggung jawab:",options:["Jangan ikut menyebarkan lebih jauh, minta yang membagikan menghapusnya, & dukung teman yang dirugikan; laporkan ke guru bila perlu","Ikut membagikannya juga karena foto itu sudah tersebar, dan menurutmu satu orang lagi yang menyebarkan tidak akan membuat bedanya","Menonton saja tanpa melakukan apa pun, karena itu bukan urusanmu dan bukan salahmu, walaupun temanmu jelas sedang dirugikan"],answer:0,explain:"Setiap orang di rantai penyebaran punya pilihan untuk berhenti menyebarkannya. Tidak ikut serta & mendukung yang dirugikan adalah sikap yang benar.",hint:"Hentikan penyebaran & dukung yang dirugikan, atau ikut sebar / diam?"},
{n:89,type:"mcq",micro:"Skenario: menyeimbangkan pengawasan orang tua & privasi",q:"Orang tua ingin memantau media sosialmu untuk keamanan, tapi kamu ingin tetap punya ruang privasi wajar. Cara sehat menyikapinya:",options:["Menyembunyikan semua akun dari orang tua, termasuk membuat akun kedua yang rahasia, agar privasimu tidak tersentuh","Diskusikan bersama: batas apa yang masuk akal bagi kedua pihak, & tunjukkan bahwa kamu bisa dipercaya membuat keputusan yang baik seiring waktu","Menolak semua bentuk pengawasan tanpa mau berdiskusi, dan marah setiap kali orang tua menanyakan apa yang kamu lakukan di internet"],answer:1,explain:"Kepercayaan dibangun lewat komunikasi & bukti konsisten, bukan dengan menyembunyikan sepenuhnya atau menolak keras tanpa dialog.",hint:"Diskusikan & bangun kepercayaan, atau menolak keras / menyembunyikan semua?"},
{n:90,type:"order",micro:"Proyek: audit jejak digital sebulan",q:"Urutkan langkah proyek 'audit jejak digital' selama sebulan.",items:["Minggu 1: cari namamu di internet & catat semua yang ditemukan","Minggu 2: tinjau pengaturan privasi di 3 akun utama & sesuaikan","Minggu 3: bersihkan/edit unggahan lama yang tidak lagi mewakili dirimu","Minggu 4: buat 'aturan pribadi' untuk posting ke depan & terapkan pada satu unggahan baru sebagai latihan"],answer:[0,1,2,3],explain:"Lihat gambaran saat ini → perkuat pengaturan → bersihkan yang lama → buat aturan & praktikkan ke depan. Dari refleksi ke perbaikan ke kebiasaan baru.",hint:"Membersihkan unggahan lama sebelum atau sesudah meninjau pengaturan privasi?"},
{n:91,type:"mcq",micro:"Skenario: unggahan viral tak terduga",q:"Unggahan biasamu tiba-tiba jadi viral & mendapat perhatian dari orang tak dikenal secara masif. Sikap yang bijak:",options:["Menikmati perhatian itu tanpa memeriksa pengaturan akunmu, sebab makin banyak orang yang melihat berarti makin baik untuk dirimu","Menghapus semua akun dengan panik tanpa menyimpan data dan tanpa memberi tahu orang dewasa yang bisa membantu","Tinjau ulang pengaturan privasi & audiens, waspada pada komentar/pesan mencurigakan, & minta bantuan orang dewasa bila situasinya terasa berat"],answer:2,explain:"Perhatian besar & tiba-tiba membawa risiko baru (termasuk dari orang jahat). Meninjau ulang pengaturan & tetap waspada adalah respons yang seimbang.",hint:"Tinjau ulang pengaturan & waspada, atau abaikan / panik menghapus semua?"},
{n:92,type:"tf",micro:"Jejak digital bagian dari literasi hidup",q:"Benar atau Salah: Kemampuan mengelola jejak digital & privasi adalah bagian dari keterampilan hidup yang relevan di sekolah, pekerjaan, & hubungan sosial di masa depan.",answer:true,explain:"Seiring hidup makin terhubung dengan dunia digital, keterampilan ini terus relevan & makin penting seiring bertambahnya tanggung jawab.",hint:"Keterampilan hidup yang relevan luas, atau hanya untuk anak sekolah?"},
{n:93,type:"mcq",micro:"Skenario: menolak dengan sopan permintaan berbagi berlebihan",q:"Sebuah aplikasi kuis meminta akses penuh ke daftar temanmu untuk 'melihat hasil kuis teman-temanmu'. Sikap yang bijak:",options:["Tolak izin itu; fungsi hiburan sederhana seperti kuis biasanya tidak butuh akses seluas itu","Berikan izin itu karena penasaran, dan menurutmu aplikasi kuis tidak akan menyalahgunakan daftar temanmu","Berikan izin lalu bagikan hasilnya ke daftar temanmu supaya mereka ikut mencoba kuis yang sama"],answer:0,explain:"Menilai kewajaran izin terhadap manfaat yang didapat (sekadar hiburan) membantu menolak permintaan yang berlebihan.",hint:"Tolak karena tidak sepadan, atau berikan demi penasaran?"},
{n:94,type:"mcq",micro:"Skenario: menjelaskan privasi ke adik",q:"Adikmu baru punya akun pertama & senang membagikan segalanya. Cara mengajarkan privasi tanpa membuatnya takut:",options:["Biarkan dia belajar dari kesalahan besar yang mungkin terjadi, sebab pengalaman pahit adalah guru terbaik soal privasi","Ajarkan lewat contoh sederhana & positif ('bagikan ini boleh, ini lebih baik ditanyakan dulu ke kita'), bukan hanya larangan menakutkan","Larang dia memakai internet sampai dewasa, supaya ia tidak mengenal risiko dan tidak punya jejak digital"],answer:1,explain:"Mengajarkan lewat contoh konkret & positif lebih efektif & tidak menakutkan dibanding larangan tanpa penjelasan atau membiarkan tanpa bimbingan.",hint:"Ajarkan lewat contoh positif, atau larang total / biarkan tanpa bimbingan?"},
{n:95,type:"tf",micro:"Kendali bertambah seiring usia & pengalaman",q:"Benar atau Salah: Kemampuan mengelola jejak digital & privasi dengan bijak adalah keterampilan yang tumbuh seiring pengalaman & pembelajaran, bukan sesuatu yang harus langsung sempurna.",answer:true,explain:"Seperti keterampilan lain, wajar melakukan kesalahan & belajar darinya. Yang penting terus memperbaiki kebiasaan seiring waktu.",hint:"Tumbuh seiring pengalaman, atau harus langsung sempurna?"},
{n:96,type:"mcq",micro:"Skenario: menilai berita tentang kebocoran data",q:"Berita menyebut sebuah layanan yang kamu pakai mengalami kebocoran data. Langkah yang tepat:",options:["Abaikan berita itu karena kamu yakin tidak berpengaruh padamu, dan tak perlu mengganti sandi atau memeriksa data","Hapus semua akun internetmu dengan panik tanpa membedakan yang terdampak, lalu berhenti memakai layanan digital","Ganti kata sandi akun itu segera, periksa apakah data lain (kartu, alamat) ikut bocor, & waspadai pesan phishing yang mungkin menyusul"],answer:2,explain:"Respons yang tenang & terarah (ganti sandi, periksa dampak, waspada lanjutan) lebih efektif daripada mengabaikan atau bereaksi berlebihan.",hint:"Ganti sandi & periksa dampak & waspada, atau abaikan / panik hapus semua?"},
{n:97,type:"mcq",micro:"Menilai pemahaman diri",q:"Tanda kamu sudah cukup memahami jejak digital & privasi:",options:["Kamu berpikir sebelum berbagi, tahu mengatur privasi, sadar apa yang dikumpulkan, & bisa menjelaskan kenapa ini penting ke orang lain","Kamu berhenti memakai internet sejak mempelajari jejak digital, dan menyuruh teman-temanmu melakukan hal yang sama","Kamu hafal istilah 'jejak digital', tetapi tetap memposting tanpa berpikir dan tidak mengecek pengaturan privasi"],answer:0,explain:"Pemahaman sejati terlihat dari perubahan kebiasaan nyata & kemampuan menjelaskan, bukan sekadar tahu istilahnya atau menghindari internet total.",hint:"Berubah kebiasaan & bisa menjelaskan, atau berhenti total / hafal istilah tanpa berubah?"},
{n:98,type:"mcq",micro:"Jejak digital & masyarakat",q:"Selain tanggung jawab pribadi, menjaga jejak digital yang sehat juga bagian dari...",options:["Tanggung jawab yang dimiliki perusahaan teknologi besar, sedangkan pengguna biasa tidak punya peran di dalamnya","Membangun budaya digital yang lebih menghormati privasi & keselamatan semua orang, bukan hanya diri sendiri","Urusan pribadi yang tidak berhubungan dengan orang lain, sehingga tidak perlu dibicarakan atau diajarkan"],answer:1,explain:"Kebiasaan baik individu (minta izin, tidak menyebar info orang lain sembarangan) ikut membangun lingkungan digital yang lebih aman bagi semua.",hint:"Membangun budaya digital yang lebih baik bersama, atau urusan pribadi semata?"},
{n:99,type:"mcq",micro:"Inti keterampilan",q:"Inti dari 'jejak digital & privasi':",options:["Hindari internet sepenuhnya selamanya agar tidak punya jejak digital apa pun, dan jangan berbagi apa pun kepada siapa pun juga di mana saja, sekalipun untuk belajar atau berkarya","Bagikan semua hal tanpa berpikir panjang karena jejak digital toh tidak bisa dihindari, jadi tidak perlu mengelola siapa yang bisa melihat apa atau memikirkan dampaknya nanti","Sadari bahwa aktivitas daringmu meninggalkan jejak yang bisa dilihat luas & bertahan lama; kelola dengan sengaja siapa melihat apa, & pertimbangkan dampaknya sebelum berbagi"],answer:2,explain:"Kesadaran + kendali yang disengaja + pertimbangan dampak. Bukan menghindari internet, bukan pula berbagi tanpa pikir.",hint:"Sadar + kendali + pertimbangkan dampak, atau hindari total / bagikan tanpa pikir?"},
{n:100,type:"open",micro:"Kapstone: piagam jejak digital pribadi",q:"Tulis 'piagam jejak digital' pribadimu. Sertakan: (a) 3-5 prinsip yang akan kamu pegang saat berbagi online, (b) untuk tiap prinsip, satu contoh tindakan konkret, (c) daftar 'sebelum posting, aku akan bertanya...' berisi minimal 3 pertanyaan untuk diri sendiri, (d) satu komitmen terkait menghormati privasi orang lain, (e) bagaimana kamu akan meninjau & memperbarui piagam ini seiring waktu.",explain:"Jawaban baik: 3-5 prinsip yang mencakup kendali audiens, kehati-hatian lokasi/waktu nyata, menghormati orang lain, pembersihan berkala, & keseimbangan (bukan hanya larangan), masing-masing dengan tindakan yang benar-benar bisa dilakukan; minimal 3 pertanyaan pra-posting yang tajam & spesifik; komitmen yang jelas soal privasi orang lain; & rencana peninjauan berkala yang konkret (jadwal & cara mengecek kepatuhan sendiri).",hint:"Bagian (c) & (e) sering lemah, buat pertanyaan pra-posting benar-benar spesifik (bisa dijawab ya/tidak dengan jelas) & rencana peninjauan dengan jadwal & cara pengecekan yang nyata.",sample:"(a) & (b) Prinsip & tindakan: (1) 'Aku memilih audiens dengan sadar', tindakan, memeriksa pengaturan siapa yang bisa melihat sebelum tiap unggahan penting, bukan otomatis publik. (2) 'Aku tidak membagikan waktu nyata & lokasi spesifik secara publik', tindakan, menandai lokasi hanya setelah aku pergi dari tempat itu, & tidak pernah menandai rumah sendiri. (3) 'Aku menghormati privasi orang lain seperti privasiku sendiri', tindakan, selalu bertanya izin sebelum memposting foto/info orang lain. (4) 'Aku memeriksa & membersihkan jejak lama secara berkala', tindakan, sekali tiap 3 bulan meninjau unggahan lama & pengaturan privasi akun utamaku. (5) 'Aku membangun jejak yang jujur, bukan yang dipaksakan sempurna', tindakan, sesekali membagikan hal biasa & manusiawi, bukan hanya momen yang terlihat sempurna. (c) Sebelum posting, aku akan bertanya: 'Siapa yang bisa melihat ini & apakah aku nyaman dengan itu? Apakah ada info sensitif (lokasi, jadwal, dokumen) yang tak sengaja ikut terlihat? Apakah aku akan tetap nyaman dengan ini 3-5 tahun lagi? Apakah ini melibatkan orang lain yang perlu kutanya izinnya dulu?' (d) Komitmen menghormati privasi orang lain: aku tidak akan memposting foto, info, atau cerita tentang orang lain tanpa izin mereka, & aku akan menghapus/mengubah kalau ada yang keberatan setelahnya, tanpa berdebat panjang soal itu 'fotoku'. (e) Meninjau piagam: aku akan membaca ulang piagam ini tiap awal semester baru (kira-kira 2 kali setahun), menyesuaikannya kalau ada platform baru yang kupakai atau pelajaran baru yang kudapat, & mengecek jujur apakah aku benar-benar mengikutinya lewat meninjau 5 unggahan terakhirku."},
];
